from pathlib import Path
import json, re, zlib, base64

B64 = "[... ELLIPSIZATION ...]"
mapping = json.loads(zlib.decompress(base64.b64decode(B64)).decode("utf-8"))

p = Path("index.html")
s = p.read_text(encoding="utf-8")
marker = "window.POLICE69_DATA="
start = s.index(marker) + len(marker)
end = s.index("</script>", start)
raw = s[start:end].strip()
if raw.endswith(";"):
    raw = raw[:-1]
data = json.loads(raw)

seen = 0
for sec in data["sectionTests"]:
    for q in sec["questions"]:
        rw = mapping[q["q"]]
        q["explanation"] = rw["explanation"]
        q["tip"] = rw["tip"]
        q["explanationLevel"] = "E2-teaching"
        seen += 1

assert seen == 150
sec_by_stem = {q["q"]: q for sec in data["sectionTests"] for q in sec["questions"]}
assert all(q["q"] in sec_by_stem for q in data["diagnostic"])
for q in data["diagnostic"]:
    src = sec_by_stem[q["q"]]
    q["explanation"] = src["explanation"]
    q["tip"] = src["tip"]
    q["explanationLevel"] = "E2-teaching"

data["explanationOverhaul"] = {
    "version": "E2",
    "date": "2026-10-04",
    "scope": "sectionTests + diagnostic",
    "uniqueRewritten": 150,
    "diagnosticPropagated": 60,
    "standard": "why correct -> rule/method -> trap when useful -> reusable memory tip"
}

newraw = json.dumps(data, ensure_ascii=False, separators=(",", ":"))
s = s[:start] + newraw + ";\n" + s[end:]

oldfb = "${show?\`<div class=\"feedback ${sel===q.answer?'good':'bad'}\"><b>${sel===q.answer?'✓ ถูก':'✕ ผิด · คำตอบ '+q.answer}</b><br>${esc(q.explanation||'')}</div>\`:'')}"
newfb = "${show?\`<div class=\"feedback ${sel===q.answer?'good':'bad'}\"><b>${sel===q.answer?'✓ ถูก':'✕ ผิด · คำตอบ '+q.answer}</b><div class=\"reason\"><b>เหตุผล:</b> ${esc(q.explanation||'ยังไม่มีคำอธิบาย')}</div>${q.tip?\`<div class=\"memory-tip\">💡 <b>จำง่าย:</b> ${esc(String(q.tip).replace(/^จำง่าย:\\s*/,''))}</div>\`:''}</div>\`:'')}"
if oldfb in s:
    s = s.replace(oldfb, newfb)

css = ".feedback{margin-top:12px;padding:12px;border-left:4px solid var(--accent);background:var(--card);border-radius:10px}"
if ".feedback .memory-tip" not in s and css in s:
    s = s.replace(css, css + ".feedback .reason{margin-top:8px;line-height:1.55;color:var(--text)}.feedback .memory-tip{margin-top:9px;padding:9px 10px;border-radius:10px;background:var(--soft);color:var(--text);font-size:14px;line-height:1.45}.feedback.good .memory-tip{background:var(--soft-good)}")

s = re.sub(r'<span class="version-badge">[^<]*</span>', '<span class="version-badge">UX v7.2 · E2</span>', s, count=1)

# Regression guard: explanation scope must be complete.
st = s.index(marker) + len(marker)
en = s.index("</script>", st)
rr = s[st:en].strip()
if rr.endswith(";"):
    rr = rr[:-1]
d2 = json.loads(rr)
qs = [q for sec in d2["sectionTests"] for q in sec["questions"]]
assert len(qs) == 150 and len(d2["diagnostic"]) == 60
assert all(len(q.get("explanation","")) >= 45 for q in qs)
assert all(q.get("tip") for q in qs)
assert all(q.get("explanationLevel") == "E2-teaching" for q in qs + d2["diagnostic"])

p.write_text(s, encoding="utf-8")
print("E2 applied:", len(qs), "section questions +", len(d2["diagnostic"]), "diagnostic")
